import { Color } from "three/src/math/Color.js";
import { Matrix2 } from "three/src/math/Matrix2.js";
import { Matrix3 } from "three/src/math/Matrix3.js";
import { Matrix4 } from "three/src/math/Matrix4.js";
import { Vector2 } from "three/src/math/Vector2.js";
import { Vector3 } from "three/src/math/Vector3.js";
import { Vector4 } from "three/src/math/Vector4.js";
import Node from "./Node.js";
import StructTypeNode, { MembersLayout } from "three/src/nodes/core/StructTypeNode.js";

declare class StructNode extends Node {
    values: Node[];

    constructor(structLayoutNode: StructTypeNode, values: Node[]);
}

export default StructNode;

export type StructValue =
    | Node
    | number
    | boolean
    | Vector2
    | Vector3
    | Vector4
    | Matrix2
    | Matrix3
    | Matrix4
    | Color;

export interface Struct {
    (): StructNode;
    (values: Node[]): StructNode;
    (...values: StructValue[]): StructNode;
}

export const struct: (membersLayout: MembersLayout, name?: string | null) => Struct;
